        elif circuit_library == 'braket':
            return self._braket_gate(circuit)
        elif circuit_library == 'vector':
            return self._vector_gate(circuit)

    @abstractmethod
    def _ibm_gate(self):

        pass

    @abstractmethod
    def _pyquil_gate(self):

        pass

    @abstractmethod
    def _braket_gate(self):

        pass

    @abstractmethod
    def _vector_gate(self):

